window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-912d47228591caa4"]={"versions": [{"id": "FIG-912d47228591caa4", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines internen Teilschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 5). Das Diagramm definiert den Ablauf des Teilschritts „Increment Counter“ im Ausführungskontext der Funktion <code>E2E_P05Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext: Funktionsaufruf <code>E2E_P05Protect()</code> (dargestellt als abgerundetes Aktivitätssymbol mit Aufrufsymbol).\n</li><li>Aktion: <code>State-&gt;Counter++</code> zur Manipulation des Zustandsstruktur-Attributs <code>Counter</code>.\n</li><li>Kommentar/Notiz: Ergänzende Spezifikation zum Zähler: Datentyp <code>uint8</code> mit Überlaufverhalten (<code>After 0xFF, the next value is 0.</code>), assoziiert mit der Aktion <code>State-&gt;Counter++</code>.\n</li><li>Steuerungsknoten: Initialknoten (Start) und Aktivitätsendknoten (Ende).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Kontrollfluss führt direkt zur Ausführung der Aktion <code>State-&gt;Counter++</code>, bei der der Zählerwert um 1 erhöht wird (modulo 256 bei Überlauf von 0xFF nach 0).\n</li><li>Kontrollfluss terminiert im Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Implementierungen von E2E Profile 5: Die Zählervariable in der Zustandsstruktur muss als 8-Bit-Ganzzahl (<code>uint8</code>) geführt werden. Nach Erreichen des Maximalwerts <code>0xFF</code> (255) ist ein deterministischer Überlauf auf <code>0</code> sicherzustellen.</p>"}, {"id": "FIG-62205617da1d5ac4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines internen Teilschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 5). Das Diagramm definiert den Ablauf des Teilschritts „Increment Counter“ in den Ausführungskontexten der Funktionen <code>E2E_P05Protect()</code> und <code>E2E_P05Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontexte: Funktionsaufrufe <code>E2E_P05Protect()</code> und <code>E2E_P05Forward()</code> (jeweils dargestellt als abgerundetes Aktivitätssymbol mit Aufrufsymbol).\n</li><li>Aktion: <code>State-&gt;Counter++</code> zur Manipulation des Zustandsstruktur-Attributs <code>Counter</code>.\n</li><li>Kommentar/Notiz: Ergänzende Spezifikation zum Zähler: Datentyp <code>uint8</code> mit Überlaufverhalten (<code>After 0xFF, the next value is 0.</code>), assoziiert mit der Aktion <code>State-&gt;Counter++</code>.\n</li><li>Steuerungsknoten: Initialknoten (Start) und Aktivitätsendknoten (Ende).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Kontrollfluss führt direkt zur Ausführung der Aktion <code>State-&gt;Counter++</code>, bei der der Zählerwert um 1 erhöht wird (modulo 256 bei Überlauf von 0xFF nach 0).\n</li><li>Kontrollfluss terminiert im Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Implementierungen von E2E Profile 5: Sowohl beim Absichern (<code>E2E_P05Protect()</code>) als auch beim Weiterleiten (<code>E2E_P05Forward()</code>) muss die Zählervariable in der Zustandsstruktur als 8-Bit-Ganzzahl (<code>uint8</code>) geführt werden. Nach Erreichen des Maximalwerts <code>0xFF</code> (255) ist ein deterministischer Überlauf auf <code>0</code> sicherzustellen.</p>"}, {"id": "FIG-e30ae182ca67abcd", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines internen Teilschritts innerhalb des AUTOSAR E2E-Protokolls (Profile 5). Das Diagramm definiert den Ablauf des Teilschritts „Increment Counter“ in den Ausführungskontexten der Funktionen <code>E2E_P05Protect()</code> und <code>E2E_P05Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontexte: Funktionsaufrufe <code>E2E_P05Protect()</code> und <code>E2E_P05Forward()</code> (jeweils dargestellt als abgerundetes Aktivitätssymbol mit Aufrufsymbol).\n</li><li>Aktion: <code>State-&gt;Counter++</code> zur Manipulation des Zustandsstruktur-Attributs <code>Counter</code>.\n</li><li>Kommentar/Notiz: Ergänzende Spezifikation zum Zähler: Datentyp <code>uint8</code> mit Überlaufverhalten (<code>After 0xFF, the next value is 0.</code>), assoziiert mit der Aktion <code>State-&gt;Counter++</code>.\n</li><li>Steuerungsknoten: Initialknoten (Start) und Aktivitätsendknoten (Ende).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Kontrollfluss führt direkt zur Ausführung der Aktion <code>State-&gt;Counter++</code>, bei der der Zählerwert um 1 erhöht wird (modulo 256 bei Überlauf von 0xFF nach 0).\n</li><li>Kontrollfluss terminiert im Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Implementierungen von E2E Profile 5: Sowohl beim Absichern (<code>E2E_P05Protect()</code>) als auch beim Weiterleiten (<code>E2E_P05Forward()</code>) muss die Zählervariable in der Zustandsstruktur als 8-Bit-Ganzzahl (<code>uint8</code>) geführt werden. Nach Erreichen des Maximalwerts <code>0xFF</code> (255) ist ein deterministischer Überlauf auf <code>0</code> sicherzustellen.</p>"}], "trans": [{"from": "FIG-912d47228591caa4", "to": "FIG-62205617da1d5ac4", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neuer Aufrufkontext hinzugefügt: Aktivitätssymbol <code>E2E_P05Forward()</code> links unter <code>E2E_P05Protect()</code>, wodurch der Teilschritt „Increment Counter“ auch für die Weiterleitungsfunktion gilt.\n</li></ul>"}, {"from": "FIG-62205617da1d5ac4", "to": "FIG-e30ae182ca67abcd", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
